package com.quiz.servlet;
import com.quiz.dao.*; import com.quiz.model.*; import java.io.*; import java.sql.SQLException; import java.util.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/teacher/results") public class TeacherResultServlet extends HttpServlet { private final QuizDAO qd=new QuizDAO();private final ResultDAO rd=new ResultDAO(); protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");try{List<Quiz> quizzes=qd.findByTeacher(u.getId());int quizId=0;try{quizId=Integer.parseInt(req.getParameter("quizId"));}catch(Exception ignored){}List<TeacherResult> results=quizId>0?rd.findByTeacherAndQuiz(u.getId(),quizId):Collections.emptyList();int high=0,pass=0,sum=0;for(TeacherResult r:results){sum+=r.getPercent();high=Math.max(high,r.getPercent());if(r.isPassed())pass++;}req.setAttribute("quizzes",quizzes);req.setAttribute("selectedQuizId",quizId);req.setAttribute("results",results);req.setAttribute("totalAttempts",results.size());req.setAttribute("averageScore",results.isEmpty()?"0.0":String.format("%.1f",(double)sum/results.size()));req.setAttribute("highestScore",high);req.setAttribute("passRate",results.isEmpty()?0:pass*100/results.size());req.getRequestDispatcher("/WEB-INF/views/teacher-results.jsp").forward(req,resp);}catch(SQLException e){throw new ServletException("Could not load assessment results",e);}}}
